#!/bin/bash# Exit on first errorset -e# Wait for postgres to be readyecho "Waiting for postgres..."while ! nc -z $DB_HOST $DB_PORT; do  sleep 0.1doneecho "PostgreSQL started"# Run migrationsecho "Applying database  migrations..."python manage.py migrate# Check/Create Superuserecho "Checking/Creating Superuser..."python manage.py shell -c "import osfrom django.contrib.auth import get_user_modelUser = get_user_model()admin_username = os.getenv('DJANGO_SUPERUSER_USERNAME', 'admin')admin_email = os.getenv('DJANGO_SUPERUSER_EMAIL', 'admin@proios.com')admin_password = os.getenv('DJANGO_SUPERUSER_PASSWORD', 'admin123')if not User.objects.filter(username=admin_username).exists():    User.objects.create_superuser(        username=admin_username,        email=admin_email,        password=admin_password,        role='OWNER'    )    print(f'>>> Superuser {admin_username} created successfully.')else:    print(f'>>> Superuser {admin_username} already exists. Skipping creation.')    "# Collect static filesecho "Collecting static files..."python manage.py collectstatic --noinput# ==========================================# INICIO DEL SERVIDOR WEB# ==========================================# Arrancamos Gunicorn directamente (el único dueño de la memoria RAM)echo "Iniciando servidor web Gunicorn..."exec "$@"